     "summary": "热点聚焦 国务院第十二次全体会议： 国务院总理李强8月17日主持召开国务院第十二次全体会议。李强强调，要着力保持经济平稳运行，坚持扩大内需这个战略基点，聚焦主要矛盾问题，抓住一些链条长、体量大的领域持续用力，进一步做强国内大循环，把内需潜力充分释放出来。加快落实“六张网”建设实施方案，创新投融资机制吸引社会资本。要强化科技赋能，加快新旧动能转换，加大新兴支柱产业和未来产业培育支持力度，持续推动传统产业转型升级，夯实实体经济根基。 宇树科技将上市： 宇树科技(688836.SH",
